/**
 * WRITEUPS
 * ------------------------------------------------------------
 * Pulls from writeups.json (auto-generated by scripts/build-writeups.js
 * from the writeups/ folder — see README) instead of a hand-typed array.
 *
 * To add one: create writeups/your-post.html with a <title> and the
 * usual meta tags (description, date, tags, category), then push.
 * A GitHub Action rebuilds writeups.json for you — nothing to edit here.
 *
 * category: "writeups" (default) shows on writeups.html.
 * category: "azure" shows in the Azure page's writeups tab instead —
 * see js/azure-writeups.js.
 * ------------------------------------------------------------
 */

fetch("writeups.json")
  .then(r => r.json())
  .then(items => {
    const general = items.filter(w => (w.category || "writeups") === "writeups");
    renderWriteupList(general, "writeup-list");
  })
  .catch(() => {
    renderWriteupList([], "writeup-list");
  });